import uuid
from decimal import Decimal
from datetime import datetime
from typing import TYPE_CHECKING, List, Dict, Any
from sqlalchemy import String, Numeric, DateTime, ForeignKey, CheckConstraint, Text, Index, func
from sqlalchemy.dialects.postgresql import UUID, JSONB
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.core.database import Base

if TYPE_CHECKING:
    from app.models.account import Account
    from app.models.user import User


class GraphFinding(Base):
    """Advisory money-flow graph finding generated by LedgerGraph temporal analysis."""

    __tablename__ = "graph_findings"

    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        default=uuid.uuid4,
    )
    pattern_type: Mapped[str] = mapped_column(
        String(50),
        nullable=False,
        index=True,
    )
    detector_version: Mapped[str] = mapped_column(
        String(30),
        nullable=False,
        default="ledgergraph-v1.0",
    )
    severity: Mapped[str] = mapped_column(
        String(20),
        nullable=False,
        default="MEDIUM",
    )
    heuristic_score: Mapped[Decimal] = mapped_column(
        Numeric(precision=5, scale=4),
        nullable=False,
    )
    primary_account_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("accounts.id", ondelete="RESTRICT"),
        nullable=False,
        index=True,
    )
    window_start: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
    )
    window_end: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
    )
    involved_transfer_ids: Mapped[List[str]] = mapped_column(
        JSONB,
        nullable=False,
        server_default="[]",
    )
    involved_account_ids: Mapped[List[str]] = mapped_column(
        JSONB,
        nullable=False,
        server_default="[]",
    )
    evidence: Mapped[Dict[str, Any]] = mapped_column(
        JSONB,
        nullable=False,
        server_default="{}",
    )
    explanation: Mapped[str] = mapped_column(
        Text,
        nullable=False,
    )
    review_status: Mapped[str] = mapped_column(
        String(20),
        nullable=False,
        default="PENDING",
        index=True,
    )
    reviewed_by_user_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("users.id", ondelete="RESTRICT"),
        nullable=True,
    )
    review_notes: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
    )
    reviewed_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False,
        index=True,
    )

    # Relationships
    primary_account: Mapped["Account"] = relationship("Account")
    reviewed_by_user: Mapped["User"] = relationship("User")

    __table_args__ = (
        CheckConstraint(
            "heuristic_score >= 0.0000 AND heuristic_score <= 1.0000",
            name="chk_graph_heuristic_score_range",
        ),
        CheckConstraint(
            "severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')",
            name="chk_graph_severity_valid",
        ),
        CheckConstraint(
            "review_status IN ('PENDING', 'CLEARED', 'CONFIRMED_FRAUD', 'ESCALATED')",
            name="chk_graph_review_status_valid",
        ),
        CheckConstraint(
            "pattern_type IN ('FAN_IN', 'FAN_OUT', 'RAPID_PASS_THROUGH', 'MULTI_HOP_LAYERING', 'CIRCULAR_FLOW', 'BURST_VELOCITY')",
            name="chk_graph_pattern_type_valid",
        ),
        Index(
            "idx_graph_findings_pending_queue",
            heuristic_score.desc(),
            created_at.desc(),
            postgresql_where=(review_status == "PENDING"),
        ),
    )
